-- LAN-584의 추가 예문 1·2번 영어 칩만 교정하고 원본 불일치 시 전체 적용을 취소한다.
-- 검수 범위와 FE 검증 근거: docs/tasks/LAN-584/plan.md.
-- 한국어 배열·이미지·나머지 예문·메타데이터를 포함한 다른 필드는 보존한다.
LOCK TABLE writing_expression IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE lan584_updates (
    expression_id BIGINT NOT NULL CHECK (expression_id BETWEEN 1 AND 4000),
    example_number INTEGER NOT NULL CHECK (example_number IN (1, 2)),
    expression_source TEXT NOT NULL,
    expected_example JSONB NOT NULL,
    words JSONB NOT NULL,
    choices JSONB NOT NULL,
    PRIMARY KEY (expression_id, example_number)
) ON COMMIT DROP;

INSERT INTO lan584_updates
SELECT (value ->> 'expressionId')::BIGINT, (value ->> 'exampleNumber')::INTEGER,
       value ->> 'expressionSource', value -> 'expected',
       value -> 'sentenceWords', value -> 'sentenceWordChoices'
FROM jsonb_array_elements($lan584_data$
